const el=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let token=sessionStorage.getItem('village-teacher-token')||'',data=null,editing=false;
async function request(url,body,auth=token){const r=await fetch(url,{method:body?'POST':'GET',headers:{'content-type':'application/json',...(auth?{authorization:'Bearer '+auth}:{})},...(body?{body:JSON.stringify(body)}:{}),cache:'no-store',signal:AbortSignal.timeout(15000)});const out=await r.json();if(!r.ok)throw Error(out.error||'처리하지 못했어요.');return out}
function csv(filename,rows){const text='\ufeff'+rows.map(r=>r.map(x=>'"'+(/^[=+@-]/.test(String(x))?"'"+String(x):String(x)).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function show(d,force=false){data=d;showTeacherStory(d);el('#teacherLogin').hidden=true;el('#teacherDashboard').hidden=false;const r=d.room;el('#roomTitle').textContent='학급 '+r.code;el('#teacherSummary').innerHTML=`<span><b>${d.players.length}</b>전체 학생</span><span><b>${d.players.filter(p=>p.online).length}</b>최근 접속</span><span><b>${d.offers.length}</b>교환 제안</span><span><b>${r.coop.join(' / ')}</b>공동 식탁 · 각 ${r.goal}개 목표</span>`;if(force||!editing){el('#roomDay').value=r.day;el('#roomWeather').value=r.weather;el('#roomPhase').value=r.phase;el('#roomMarket').value=r.market?'1':'0';el('#roomPaused').value=r.paused?'1':'0'}el('#teacherRoster').innerHTML='<table><thead><tr><th>학생</th><th>연결</th><th>직업</th><th>수확</th><th>코인</th><th>상추/우유/사과/생선</th><th>기여</th></tr></thead><tbody>'+d.players.map(p=>`<tr><td>${esc(p.name)}<small style="display:block">${esc(p.accountName||'')}</small></td><td>${p.online?'접속 중':'대기'}</td><td>${(p.rolePending?'선택 전':['채소','낙농','과수','양식'][p.job])}</td><td>${p.picked}</td><td>${p.coins}</td><td>${p.stock.join(' / ')}</td><td>${p.donated.join(' / ')}</td></tr>`).join('')+'</tbody></table>'}
el('#joinTeacher').onclick=async()=>{try{const d=await request('/api/join',{roomCode:el('#teacherRoom').value,code:el('#teacherCode').value},'');if(!d.teacher)throw Error('교사 입장 코드를 사용해 주세요.');managedRoom='';sessionStorage.removeItem('village-managed-room');token=d.token;sessionStorage.setItem('village-teacher-token',token);show(d,true)}catch(e){el('#teacherError').textContent=e.message}};
el('#createClass').onclick=async()=>{const b=el('#createClass');b.disabled=true;try{const d=await request('/api/create',{setupKey:el('#setupKey').value,size:Number(el('#classSize').value),roleMode:el('#createRoleMode').value},'');el('#setupKey').value='';el('#newCodes').hidden=false;el('#newCodes').innerHTML=`<h2>학급 ${esc(d.roomCode)} 생성 완료</h2><p>교사 입장 코드를 별도로 보관하세요. 학생에게는 각자의 코드만 전달하세요.</p><div class="teacher-secret">${esc(d.teacherKey)}</div><button id="downloadStudentCodes" class="primary wide">학생 입장 코드 CSV 내려받기</button>`;el('#downloadStudentCodes').onclick=()=>csv(`학급-${d.roomCode}-학생코드.csv`,[['학급 코드','학생','입장 코드','역할'],...d.students.map(s=>[d.roomCode,s.name,s.code,s.role===null?'입장 후 선택':['채소','낙농','과수','양식'][s.role]])]);managedRoom='';sessionStorage.removeItem('village-managed-room');token=d.teacherKey;sessionStorage.setItem('village-teacher-token',token);show(await request('/api/state'),true)}catch(e){el('#teacherError').textContent=e.message}finally{b.disabled=false}};
document.querySelectorAll('#roomDay,#roomWeather,#roomPhase,#roomMarket,#roomPaused').forEach(x=>x.onchange=()=>editing=true);
el('#saveRoom').onclick=async()=>{el('#saveRoom').disabled=true;try{const d=await request('/api/teacher',{day:Number(el('#roomDay').value),weather:Number(el('#roomWeather').value),phase:el('#roomPhase').value,market:el('#roomMarket').value==='1',paused:el('#roomPaused').value==='1'});editing=false;show(d,true);el('#teacherStatus').textContent='학급 전체에 적용했어요.'}catch(e){el('#teacherStatus').textContent=e.message}finally{el('#saveRoom').disabled=false}};
async function refresh(){if(!token)return;try{show(await request('/api/state'))}catch(e){el('#teacherStatus').textContent='연결 확인 필요: '+e.message}}el('#teacherRefresh').onclick=refresh;el('#teacherLogout').onclick=()=>{sessionStorage.removeItem('village-teacher-token');location.reload()};el('#exportProgress').onclick=()=>{if(!data)return;csv('학급-활동현황.csv',[['학생 번호','별명','직업','수확','코인','상추','우유','사과','생선','공동기여'],...data.players.map(p=>[p.accountName||p.name,p.name,(p.rolePending?'선택 전':['채소','낙농','과수','양식'][p.job]),p.picked,p.coins,...p.stock,p.donated.reduce((a,b)=>a+b,0)])])};setInterval(()=>{if(!document.hidden)refresh()},10000);

function showTeacherStory(d){const root=el('#teacherStory'),m=d.mission;if(!m){if(root.querySelector('#startClassStory'))return;root.innerHTML=`<span class="eyetag">첫 협력 이야기 · 여러 차시</span><h2>폭우로 멈춘 마을, 내일 아침 급식을 부탁해!</h2><p>시작하면 폭우가 내리고 장터가 닫힙니다. 운송·전력 미션을 함께 해결하면 길과 창고가 복구되고, 생산한 재료를 모아 급식 준비를 완성합니다.</p><div class="teacher-grid"><label>이번 참여 인원<input id="storyParticipants" type="number" min="1" max="${d.players.length}" value="${d.players.length}"></label><button class="primary" id="startClassStory">우리 반 이야기 시작</button></div><p>참여 인원 8명당 직업 미션 1명, 4명당 재료별 1개가 필요해요(올림). 시작 후에도 교사 운영실에서 목표를 낮출 수 있습니다. 현재 재고와 활동 기록은 보존됩니다. 사과는 누적 수확 16개 뒤 과수 역할에서, 우유는 수확 80개 뒤 젖소 돌봄에서, 생선은 물가 돌봄에서 얻어요. 여러 차시에 나누어 진행할 수 있습니다.</p><p id="storyTeacherMessage" role="status"></p>`;el('#startClassStory').onclick=async()=>{const b=el('#startClassStory');b.disabled=true;try{show(await request('/api/story/start',{participants:Number(el('#storyParticipants').value)}),true)}catch(e){el('#storyTeacherMessage').textContent=e.message;b.disabled=false}};return}const names=['운송 경로','전력 복구','품질 검수','급식 인계'];root.innerHTML=`<span class="eyetag">EPISODE 01 · ${m.completed?'완료':'진행 중'}</span><h2>내일 아침 급식을 부탁해!</h2><div class="teacher-summary">${names.map((n,i)=>`<span><b>${m.counts[i]} / ${m.target}명</b>${n}</span>`).join('')}</div><p>급식 재료: ${['상추','우유','사과','생선'].map((n,i)=>n+' '+m.food[i]+'/'+m.goal).join(' · ')}</p><p>${m.completed?'모두의 일이 한 끼로 연결됐어요. 학생 화면에서 서로의 기여를 확인하고 활동을 돌아보세요.':'길·전기 복구 → 재료 모으기 → 검수 → 인계 순으로 진행됩니다. 아래 수업 운영에서 일시정지할 수 있어요.'}</p><button id="exportStory">이야기 참여 기록 CSV 저장</button>`;el('#exportStory').onclick=()=>csv('함께-만든-한끼-참여기록.csv',[['학생 번호','별명',...names,'상추','우유','사과','생선'],...d.players.map(p=>{const w=m.helpers.find(h=>h.actor===p.id)?.work||{};return [p.accountName||p.name,p.name,...Array.from({length:8},(_,i)=>w[i]||0)]})])}
